"use strict";
// A constructor-function "class" in the style of statsd clients: a function
// expression, prototype methods, a child client linked with util.inherits,
// and the whole export plus a named alias.
const util = require("util");

const Client = function (options) {
  const opts = options || {};
  this.prefix = opts.prefix || "";
  this.suffix = opts.suffix || "";
  this.sent = [];
  this.listeners = [];
};

Client.prototype.send = function (stat, value, type) {
  const line = this.prefix + stat + this.suffix + ":" + value + "|" + type;
  this.sent.push(line);
  for (const listener of this.listeners) listener(line);
  return line;
};
Client.prototype.onSent = function (listener) {
  this.listeners.push(listener);
  return this;
};
Client.prototype.increment = function (stat, value) {
  return this.send(stat, value === undefined ? 1 : value, "c");
};
Client.prototype.gauge = function (stat, value) {
  return this.send(stat, value, "g");
};
Client.prototype.close = function (callback) {
  const count = this.sent.length;
  setImmediate(() => callback(null, count));
};
Client.prototype.childClient = function (options) {
  return new ChildClient(this, options);
};

const ChildClient = function (parent, options) {
  Client.call(this, {
    prefix: parent.prefix + ((options && options.prefix) || ""),
    suffix: parent.suffix,
  });
  this.parent = parent;
};
util.inherits(ChildClient, Client);

exports = module.exports = Client;
exports.StatsD = Client;
exports.ChildClient = ChildClient;
